     CONVERT(FROM_BASE64('5pat6IeC55yf55u4wrfpu5HnjL/vvZzmtbfotLznjovkuozliJvnn63liac=') USING utf8mb4),
     CONVERT(FROM_BASE64('') USING utf8mb4),
     CONVERT(FROM_BASE64('aHR0cHM6Ly9pbWcuemx5dW4xNjguY29tL3pseS1haS12aWRlby1zdHVkaW8vaW1hZ2UvMjAyNjExMTEvMTgwNTM3X2VkNmVmZDZhMGNjMGYwMDQucG5n') USING utf8mb4),
     CONVERT(FROM_BASE64('') USING utf8mb4),
     3, 73, 0, 'published', '8UKOFV4-iyb37iqN', '2026-11-13 09:55:00', '2026-11-13 17:12:00')
ON DUPLICATE KEY UPDATE
